package com.example.lifecoach.worker

import android.app.*;import android.content.*;import androidx.core.app.NotificationCompat;import androidx.work.*;import com.example.lifecoach.R;import com.example.lifecoach.data.CoachRepository;import kotlinx.coroutines.*;import java.util.concurrent.TimeUnit
class CatchUpWorker(ctx:Context,params:WorkerParameters):CoroutineWorker(ctx,params){override suspend fun doWork():Result{CoachRepository(applicationContext).catchUp();return Result.success()}}
class BootReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){if(i.action==Intent.ACTION_BOOT_COMPLETED){WorkManager.getInstance(c).enqueueUniquePeriodicWork("catchup",ExistingPeriodicWorkPolicy.UPDATE,PeriodicWorkRequestBuilder<CatchUpWorker>(30,TimeUnit.MINUTES).build());KeepAliveService.start(c);AlarmScheduler.scheduleNext(c)}}}
class AlarmReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){CoroutineScope(Dispatchers.IO).launch{val repo=CoachRepository(c);when(i.action){Notify.ACTION_SMOKE->repo.quickSmoke();Notify.ACTION_WALK->repo.quickWalk();else->repo.catchUp()};if(i.action==null||i.action==Notify.ACTION_PROMPT){Notify.show(c,i.getStringExtra("slot")?:"教练有个问题等你")};AlarmScheduler.scheduleNext(c)}}}
object Notify{const val CHANNEL="coach";const val ACTION_SMOKE="com.example.lifecoach.SMOKE";const val ACTION_WALK="com.example.lifecoach.WALK";const val ACTION_PROMPT="com.example.lifecoach.PROMPT";fun show(c:Context,text:String){val nm=c.getSystemService(NotificationManager::class.java);nm.createNotificationChannel(NotificationChannel(CHANNEL,"教练提醒",NotificationManager.IMPORTANCE_DEFAULT));val smoke=PendingIntent.getBroadcast(c,11,Intent(c,AlarmReceiver::class.java).setAction(ACTION_SMOKE),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val walk=PendingIntent.getBroadcast(c,12,Intent(c,AlarmReceiver::class.java).setAction(ACTION_WALK),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);nm.notify(100,NotificationCompat.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("教练在").setContentText(text).addAction(0,"抽了一根",smoke).addAction(0,"出门了",walk).setAutoCancel(true).build())}}
class KeepAliveService:Service(){override fun onCreate(){super.onCreate();val nm=getSystemService(NotificationManager::class.java);nm.createNotificationChannel(NotificationChannel(Notify.CHANNEL,"教练提醒",NotificationManager.IMPORTANCE_MIN));startForeground(7,NotificationCompat.Builder(this,Notify.CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("教练在").setContentText("点开回答今天的问题").setOngoing(true).build())};override fun onBind(i:Intent?)=null;companion object{fun start(c:Context){try{if(android.os.Build.VERSION.SDK_INT>=26)c.startForegroundService(Intent(c,KeepAliveService::class.java))else c.startService(Intent(c,KeepAliveService::class.java))}catch(_:Exception){}}}}
